// ===========================================================================
//  CẤU HÌNH - chỉnh 3 khối dưới đây
// ===========================================================================
// Chế độ test: true = hạ ngưỡng 0.1 + bỏ chống lặp, ép ra tin nhắn thử.
// ⚠️ Test xong nhớ trả về false!
const TEST_MODE = false;

// NHÓM 1 - mã nền tảng / đang giữ (ngưỡng nhạy: giá ±3%, KL x2)
const WATCHLIST_CORE = ['VNM', 'FPT', 'HPG', 'MWG', 'VCB', 'MBB'];

// NHÓM 2 - mã sóng mạnh / đầu cơ (ngưỡng cao: giá ±5%, KL x2.5 - đỡ nhiễu)
const WATCHLIST_HOT = ['SSI', 'VND', 'DGC', 'STB'];

// DANH MỤC ĐANG GIỮ - khai giá vốn để nhận cảnh báo cắt lỗ / chốt lời.
// Đơn vị giá vốn GIỐNG nguồn dữ liệu (nghìn đồng): 25.5 nghĩa là 25.500đ.
// stopLossPct: lỗ vượt % này -> báo cắt lỗ. takeProfitPct: lãi vượt % này -> báo chốt lời (0 = tắt).
const PORTFOLIO = {
  // 'HPG': { costBasis: 25.5,  stopLossPct: 7, takeProfitPct: 15 },
  // 'FPT': { costBasis: 118.0, stopLossPct: 8, takeProfitPct: 0  },
};
// ===========================================================================

const THRESHOLDS = {
  core: { vol: 2.0, price: 3.0 },
  hot:  { vol: 2.5, price: 5.0 },
};
const LOOKBACK = 20;        // số phiên tính trung bình khối lượng
const SUPPRESS_HOURS = 3;   // không lặp lại cùng một cảnh báo trong N giờ

const to   = Math.floor(Date.now() / 1000);
const from = to - 60 * 60 * 24 * 90;

const headers = {
  'User-Agent': 'Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/120.0 Safari/537.36',
  'Accept': '*/*',
};

// Nguồn chính: DNSE. Dự phòng: VNDirect (tự chuyển khi DNSE lỗi).
const fetchBars = async (ticker) => {
  try {
    const res = await this.helpers.httpRequest({
      method: 'GET',
      url: 'https://services.entrade.com.vn/chart-api/v2/ohlcs/stock',
      qs: { symbol: ticker, from, to, resolution: '1D' },
      headers,
      json: true,
    });
    if (res && Array.isArray(res.t) && res.t.length) return { src: 'DNSE', d: res };
  } catch (e) { /* rơi xuống nguồn dự phòng */ }

  const res = await this.helpers.httpRequest({
    method: 'GET',
    url: 'https://dchart-api.vndirect.com.vn/dchart/history',
    qs: { symbol: ticker, resolution: 'D', from, to },
    headers: { ...headers, Referer: 'https://dchart.vndirect.com.vn/' },
    json: true,
  });
  if (res && Array.isArray(res.t) && res.t.length) return { src: 'VNDirect', d: res };
  throw new Error('cả 2 nguồn đều không có dữ liệu');
};

// Quét: 2 watchlist + mọi mã có trong danh mục
const tickers = [...new Set([...WATCHLIST_CORE, ...WATCHLIST_HOT, ...Object.keys(PORTFOLIO)])];
const groupOf = (t) => (WATCHLIST_HOT.includes(t) ? 'hot' : 'core');

// Chống lặp cảnh báo (chỉ có tác dụng khi workflow đang Active; chạy test tay không lưu trạng thái)
const sd = $getWorkflowStaticData('global');
sd.lastAlerts = sd.lastAlerts || {};
const nowMs = Date.now();
const shouldSend = (key) => {
  if (TEST_MODE) return true;
  const last = sd.lastAlerts[key] || 0;
  if (nowMs - last < SUPPRESS_HOURS * 3600 * 1000) return false;
  sd.lastAlerts[key] = nowMs;
  return true;
};

const fmtPrice = (c) => {
  const dong = c < 500 ? c * 1000 : c;
  return Math.round(dong).toLocaleString('vi-VN') + 'đ';
};

const moveAlerts = [];
const pnlAlerts  = [];
const debug = [];

for (const ticker of tickers) {
  try {
    const { src, d } = await fetchBars(ticker);
    const n = d.t.length;
    debug.push(ticker + ': OK (' + src + ', ' + n + ' phiên)');
    if (n < 5) continue;

    const close = d.c[n - 1];
    const prevClose = d.c[n - 2];
    const vol = d.v[n - 1];
    const start = Math.max(0, n - 1 - LOOKBACK);
    const hist = d.v.slice(start, n - 1);
    const avgVol = hist.reduce((s, v) => s + (v || 0), 0) / (hist.length || 1);
    const volRatio = avgVol ? vol / avgVol : 0;
    const pct = prevClose ? ((close - prevClose) / prevClose) * 100 : 0;

    // 1) Cảnh báo cắt lỗ / chốt lời theo giá vốn
    const pos = PORTFOLIO[ticker];
    if (pos && pos.costBasis) {
      const pnl = ((close - pos.costBasis) / pos.costBasis) * 100;
      if (pos.stopLossPct > 0 && pnl <= -pos.stopLossPct && shouldSend(ticker + ':stop')) {
        pnlAlerts.push('🛑 *' + ticker + '* — ' + fmtPrice(close) + ' | *lỗ ' + pnl.toFixed(1) + '%* so giá vốn ' + fmtPrice(pos.costBasis) + '\n   → Chạm ngưỡng cắt lỗ ' + pos.stopLossPct + '%. Giữ kỷ luật!');
      } else if (pos.takeProfitPct > 0 && pnl >= pos.takeProfitPct && shouldSend(ticker + ':profit')) {
        pnlAlerts.push('💰 *' + ticker + '* — ' + fmtPrice(close) + ' | *lãi +' + pnl.toFixed(1) + '%* so giá vốn ' + fmtPrice(pos.costBasis) + '\n   → Vượt mục tiêu chốt lời ' + pos.takeProfitPct + '%.');
      }
    }

    // 2) Cảnh báo biến động giá / khối lượng theo nhóm
    const th = TEST_MODE ? { vol: 0.1, price: 0.1 } : THRESHOLDS[groupOf(ticker)];
    const reasons = [];
    if (volRatio >= th.vol)        reasons.push('📈 KL đột biến x' + volRatio.toFixed(1));
    if (Math.abs(pct) >= th.price) reasons.push((pct >= 0 ? '🟢 Giá +' : '🔴 Giá ') + pct.toFixed(2) + '%');
    if (reasons.length && shouldSend(ticker + ':move:' + (pct >= 0 ? 'up' : 'down'))) {
      moveAlerts.push({
        ticker, pct,
        line: '*' + ticker + '*' + (groupOf(ticker) === 'hot' ? ' 🌊' : '') + ' — ' + fmtPrice(close) + '\n   ' + reasons.join('  |  '),
      });
    }
  } catch (e) {
    debug.push(ticker + ': ❌ ' + (e.message || String(e)));
  }
}

const sections = [];
if (pnlAlerts.length) sections.push('🚨 *DANH MỤC - CẮT LỖ / CHỐT LỜI*\n\n' + pnlAlerts.join('\n\n'));
if (moveAlerts.length) {
  const lines = moveAlerts.sort((a, b) => Math.abs(b.pct) - Math.abs(a.pct)).map(a => a.line);
  sections.push('🔔 *BIẾN ĐỘNG BẤT THƯỜNG* (🌊 = nhóm sóng)\n\n' + lines.join('\n\n'));
}

let message = '';
if (sections.length) {
  const now = new Date().toLocaleString('vi-VN', { timeZone: 'Asia/Ho_Chi_Minh' });
  message = (TEST_MODE ? '🧪 *TEST* — ' : '') + '_' + now + '_\n\n'
          + sections.join('\n\n———\n\n')
          + '\n\n_Nguồn: DNSE/VNDirect_';
}

return [{ json: { hasAlerts: sections.length > 0, count: pnlAlerts.length + moveAlerts.length, message, debug } }];
